public class ShardSourceConnector extends SourceConnector {
    private Map<String, String> props;
    private List<String> shards;

    @Override public String version() { return "2.0.1"; }
    @Override public Class<? extends Task> taskClass() { return ShardSourceTask.class; }
    @Override public ConfigDef config() { return CONFIG_DEF; }

    @Override public void start(Map<String, String> props) {
        this.props = props;
        this.shards = LedgerClient.connect(props.get("ledger.url")).listShards();   // read once
    }

    @Override public List<Map<String, String>> taskConfigs(int maxTasks) {
        List<Map<String, String>> configs = new ArrayList<>();
        for (String shard : shards) {                       // one task per shard
            Map<String, String> c = new HashMap<>(props);
            c.put("task.shards", shard);
            configs.add(c);
        }
        return configs;
    }

    @Override public void stop() { }
}

